for (const row of native) for (const [index, [name, operands, expectedHex]] of row.controls.entries()) {
  it(`native ${name} ${row.id} variant ${index}`, () => {
    const source = value(row.sourceHex);
    const expected = expectedHex === "2356414c554521" ? { kind: "error", value: "#VALUE!" }
      : name === "LENB" ? { kind: "number" as const, value: Number(new TextDecoder().decode(Uint8Array.from({ length: expectedHex.length / 2 }, (_, i) => parseInt(expectedHex.slice(i * 2, i * 2 + 2), 16)))) } : value(expectedHex);
    expect(textFunctions[name]!([source, ...operands.map(value => ({ kind: "number" as const, value } as const))], host)).toEqual(expected);
    expect(source).toEqual(value(row.sourceHex));
  });
}
it("byte slices clip native NUL visibility and reject malformed visible host text", () => {
  for (const name of ["LEFTB", "RIGHTB", "MIDB", "LENB"] as const) {
    const args = [{ kind: "string", value: "ab\0\ud800" }, ...(name === "MIDB" ? [{ kind: "number" as const, value: 1 }, { kind: "number" as const, value: 2 }] : name === "LENB" ? [] : [{ kind: "number" as const, value: 2 }])] as const;
    expect(textFunctions[name]!(args, host)).toEqual(name === "LENB" ? { kind: "number" as const, value: 2 } : { kind: "string", value: "ab" });
    expect(() => textFunctions[name]!([{ kind: "string", value: "\ud800" }, { kind: "number" as const, value: 1 }, { kind: "number" as const, value: 1 }], host)).toThrow();
  }
});
it("byte slice counts reject NaN and preserve omitted defaults", () => {
  for (const name of ["LEFTB", "RIGHTB"] as const) {
    expect(textFunctions[name]!([{ kind: "string", value: "ab" }, { kind: "number" as const, value: NaN }], host)).toEqual({ kind: "error", value: "#VALUE!" });
    expect(textFunctions[name]!([{ kind: "string", value: "ab" }], host)).toEqual({ kind: "string", value: name === "LEFTB" ? "a" : "b" });
  }
  expect(textFunctions.MIDB!([{ kind: "string", value: "ab" }, { kind: "number" as const, value: NaN }, { kind: "number" as const, value: 1 }], host)).toEqual({ kind: "error", value: "#VALUE!" });
});
it("byte slicing admits the complete result before allocating its copy", () => {
  const bounded = { ...host, context: { ...host.context, limits: { ...host.context.limits, outputBytes: 2 } } };
  for (const name of ["LEFTB", "RIGHTB", "MIDB"] as const) {
    const args = [{ kind: "string", value: "abcd" }, ...(name === "MIDB" ? [{ kind: "number" as const, value: 1 }, { kind: "number" as const, value: 4 }] : [{ kind: "number" as const, value: 4 }])] as const;
    expect(() => textFunctions[name]!(args, bounded)).toThrow("text limit exceeded");
  }
  expect(() => textFunctions.LEFTB!([{ kind: "byte-string", value: "a9617a" }, { kind: "number" as const, value: 0 }], bounded)).toThrow("text limit exceeded");
});
it("byte slicing preserves exact falsey cancellation and immutable source", () => {
  for (const name of ["LEFTB", "RIGHTB", "MIDB"] as const) for (const reason of [null, false, 0, "", Number.NaN]) {
    const source = { kind: "string", value: "ab".repeat(100) } as const;
    let ticks = 0, observed: unknown = "not-cancelled";
    const cancelled = { ...host, tick() { if (++ticks === 250) throw reason; } };
    const args = [source, ...(name === "MIDB" ? [{ kind: "number" as const, value: 1 }, { kind: "number" as const, value: 200 }] : [{ kind: "number" as const, value: 200 }])] as const;
    try { textFunctions[name]!(args, cancelled); } catch (error) { observed = error; }
    expect(Object.is(observed, reason)).toBe(true);
    expect(ticks).toBe(250);
    expect(source.value).toBe("ab".repeat(100));
  }
});
